 target=directory/(record['id']+p.suffix+'.txt');body=''.join(lines[start-1:end]);target.write_text(body)
 rec=dict(record,excerpt_path=str(target.relative_to(r)),original_start_line=start,original_end_line=end,excerpt_sha256=sha(target),scope='Exact focused window; may omit enclosing control flow. Consult full file.')
